export const TOPIC_LABEL_STORAGE_KEY = 'topic-label-overrides-v1';

export const DEFAULT_TOPIC_LABEL_MAP = {
  '2': 'コンクリート構造',
  '3': '地盤改良',
  '1': 'トンネル掘削',
  '0': '免震構造',
  '9': '管理システム',
  '6': '廃棄物処理',
  '8': '建築パネル',
  '7': '空調システム',
  '11': '掘削装置',
  '12': '基礎構造',
  '31': '配管搬送',
  '10': '建築設計',
  '5': 'トンネル測量',
  '13': '電力管理',
  '16': '屋根構造',
  '14': '構造損傷',
  '24': '電磁波シールド',
  '19': '天井構造',
  '23': '音響検査',
  '15': '照明システム',
  '17': '壁面緑化',
};

export const readTopicLabelOverrides = () => {
  try {
    const raw = localStorage.getItem(TOPIC_LABEL_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (error) {
    console.error('TOPIC表示名の読み込みに失敗:', error);
    return {};
  }
};

export const getTopicLabelMap = () => ({
  ...DEFAULT_TOPIC_LABEL_MAP,
  ...readTopicLabelOverrides(),
});

export const getTopicLabel = (topicId, topicLabelMap = DEFAULT_TOPIC_LABEL_MAP) => {
  const topicKey = String(topicId);
  return topicLabelMap[topicKey] || `TOPIC ${topicKey}`;
};

export const getTopicIdByLabel = (topicLabel, topicLabelMap = DEFAULT_TOPIC_LABEL_MAP) => {
  const matched = Object.entries(topicLabelMap).find(([, label]) => label === topicLabel);
  return matched ? matched[0] : null;
};
