import React, { useState, useEffect } from "react";
import { Card,Row,Col,Container } from "react-bootstrap";

const ProposedVisualize = ({ topic, clickData }) => {
  const [proposedData, setProposedData] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const dataPath = `${process.env.PUBLIC_URL}/data/visualize_data/topic${topic}/span=3/proposed/proposed.json`;
        const response = await fetch(dataPath);

        if (!response.ok) {
          throw new Error("データの取得に失敗しました");
        }

        const jsonData = await response.json();

        // `clickData`に対応する会社のデータを取得
        const companyData = jsonData[clickData];

        if (!companyData) {
          console.warn("指定したデータが存在しません: " + clickData);
          setProposedData([]);
          return;
        }

        // 指定されたトピックのデータを取得
        const topicData = companyData[topic];
        if (!topicData) {
          console.warn("指定したトピックが存在しません: " + topic);
          setProposedData([]);
          return;
        }

        setProposedData(topicData);
      } catch (err) {
        console.error("データの読み込み中にエラーが発生しました:", err);
        setError(err.message);
      }
    };

    fetchData();
  }, [topic, clickData]);

  if (error) {
    return <div>エラー: {error}</div>;
  }

  if (!proposedData) {
    return <div>データを読み込み中...</div>;
  }

  
  // データをカード形式で表示
const renderCard = (direction, values) => {
  let label;
  switch (direction) {
    case "upleft":
      label = "左上";
      break;
    case "upright":
      label = "右上";
      break;
    case "downleft":
      label = "左下";
      break;
    case "downright":
      label = "右下";
      break;
    default:
      label = "その他";
  }

  // カード全体の背景色を設定（方向に基づくベースカラー）
  const baseColorMap = {
    upright: "rgba(255, 188, 188, ALPHA)",   // 赤
    upleft: "rgba(255, 255, 188, ALPHA)", // 黄
    downright: "rgba(188, 221, 255, ALPHA)", // 青
    downleft: "rgba(188, 255, 188, ALPHA)" // 緑
  };

  const baseColor = baseColorMap[direction];
  const cardAlpha = 0.3; // 内部の要素数で透明度を変化
  const cardBackgroundColor = baseColor.replace("ALPHA", Math.min(cardAlpha, 1)); // 背景色を動的に設定

  return (

    <Card key={direction} className="m-3" style={{ backgroundColor: cardBackgroundColor }}>
      <Card.Body className="text-start">
        <Card.Title className="text-start">{label}</Card.Title>
        {values.slice(0, 5).map((value, index) => {
          // 順位に基づいて透明度を調整
          const alpha = 0.90 - index * 0.15; // 順位ごとに透明度を徐々に減少
          const itemBackgroundColor = baseColor.replace("ALPHA", Math.max(alpha, 0.1)); // 各アイテムの背景色

          return (
            <div
              key={index}
              className="ranking-item py-2 px-3 border-bottom"
              style={{ backgroundColor: itemBackgroundColor }}
            >
              <strong>{index + 1}位：</strong> {value || ""}
            </div>
          );
        })}
      </Card.Body>
    </Card>

  );
};
  return (
<Container>
  <Card className="text-center my-3">
    {/* Cardヘッダーで中央上部にclickDataを表示 */}
    <Card.Header style={{ backgroundColor: "#333333", color: "white", textAlign: "center" }}>
      <h5 className="mb-0">{clickData || " "}</h5>
    </Card.Header>


    <Card.Body>
      <Row>
        <Col>{renderCard("upleft", proposedData.upleft || [])}</Col>
        <Col>{renderCard("upright", proposedData.upright || [])}</Col>
      </Row>
      <Row>
        <Col>{renderCard("downleft", proposedData.downleft || [])}</Col>
        <Col>{renderCard("downright", proposedData.downright || [])}</Col>
      </Row>
    </Card.Body>
  </Card>
</Container>


  );
};
export default ProposedVisualize;